<template><div class="modal-backdrop" @click.self="close"><section class="modal" role="dialog" aria-modal="true" :aria-labelledby="titleId" tabindex="-1" @keydown.esc="close"><h2 :id="titleId">{{ approve?'Xác nhận duyệt':'Từ chối và nêu lý do' }}</h2><p>Bạn đang xử lý: <strong>{{ itemTitle }}</strong></p><label v-if="!approve" class="field">Lý do từ chối<textarea ref="reasonInput" v-model="reason" :disabled="busy" placeholder="Nhập lý do để người gửi có thể chỉnh sửa"></textarea></label><div v-if="error" class="notice error" role="alert">{{ error }}</div><div class="actions modal-actions"><button class="button" :disabled="busy" @click="close">Hủy</button><button ref="confirmButton" class="button" :class="approve?'primary':'danger'" :disabled="busy||(!approve&&!reason.trim())" @click="$emit('confirm',reason)">{{ busy?'Đang xử lý…':approve?'Duyệt':'Từ chối' }}</button></div></section></div></template>
<script setup>
import{nextTick,onBeforeUnmount,onMounted,ref}from'vue'
const props=defineProps({approve:Boolean,itemTitle:String,busy:Boolean,error:String}),emit=defineEmits(['close','confirm']),reason=ref(''),reasonInput=ref(null),confirmButton=ref(null);let opener;const titleId=`decision-${Math.random().toString(36).slice(2)}`
function close(){if(!props.busy)emit('close')}onMounted(()=>{opener=document.activeElement;nextTick(()=>props.approve?confirmButton.value?.focus():reasonInput.value?.focus())});onBeforeUnmount(()=>opener?.focus?.())
</script>
